-- WEEK-257: terugzetpunt. De allergenen zoals ze waren vóór de aanvulling van 12/11/2026 (71 ingrediënten met allergenen,
-- de rest leeg). Enkel gebruiken om de aanvulling volledig ongedaan te maken; het raakt ook allergenen die later met de hand
-- aangepast zijn.
begin;
update public.ingredienten set allergenen = '{}' where herkomst = 'beheer';
update public.ingredienten i set allergenen = a.allergenen::text[]
from (values
  ('aardappelpuree', '{melk}'), ('aburaage', '{soja}'), ('amandelmelk', '{noten}'), ('ansjovis', '{vis}'), ('augurken', '{sulfiet}'), ('beschuit', '{gluten}'), ('burrata', '{melk}'), ('camembert', '{melk}'), ('cheddar', '{melk}'), ('doubanjiang', '{soja,gluten}'), ('edamame', '{soja}'), ('eieren', '{ei}'), ('geitenkaas', '{melk}'), ('gemengde_noten', '{noten}'), ('gerookte_makreel', '{vis}'), ('gnocchi', '{gluten}'), ('gojibessenmix', '{noten}'), ('granola', '{gluten}'), ('hacheekruiden', '{gluten}'), ('hazelnootburger', '{noten}'), ('inktvis', '{weekdieren}'), ('kaas_parmezaan', '{melk}'), ('kabeljauw', '{vis}'), ('karnemelk', '{melk}'), ('kwark_plantaardig', '{soja}'), ('macadamianoten', '{noten}'), ('macaroni', '{gluten}'), ('marsala', '{sulfiet}'), ('muesli', '{gluten}'), ('noedels', '{gluten}'), ('notenmix', '{noten}'), ('orzo', '{gluten}'), ('paneer', '{melk}'), ('paneermeel', '{gluten}'), ('pasta', '{gluten}'), ('pasta_spaghetti', '{gluten}'), ('pecannoten', '{noten}'), ('pesto_rosso', '{melk}'), ('pindakaas', '{noten}'), ('pistolet', '{gluten}'), ('plantaardige_margarine', '{soja}'), ('platbrood', '{gluten}'), ('reblochon', '{melk}'), ('rivierkreeftjes', '{schaaldieren}'), ('room', '{melk}'), ('roomkaas', '{melk}'), ('scampi', '{schaaldieren}'), ('shaoxing_wijn', '{gluten}'), ('skyr', '{melk}'), ('sobanoedels', '{gluten}'), ('sojasaus', '{soja}'), ('taartdeeg', '{gluten}'), ('tofu', '{soja}'), ('tong', '{vis}'), ('tonijn', '{vis}'), ('tonijn_blik', '{vis}'), ('tonkatsusaus', '{gluten,soja}'), ('vegetarisch_gehakt', '{soja}'), ('vegetarische_balletjes', '{soja}'), ('vegetarische_kipstukjes', '{soja}'), ('visfond', '{vis}'), ('vissticks', '{vis,gluten}'), ('woksaus', '{soja}'), ('zalm', '{vis}'), ('zalm_blik', '{vis}'), ('zeevruchten', '{schaaldieren,weekdieren}'), ('zelfrijzend_bakmeel', '{gluten}'), ('zuivelspread_knoflook', '{melk}'), ('zuivelspread_spinazie_avocado', '{melk}'), ('zure_room', '{melk}'), ('zwarte_bonen_gefermenteerd', '{soja}')
) as a(code, allergenen)
where i.code = a.code;
commit;
